queries.item:
CREATE TABLE IF NOT EXISTS `?:ab__product_sets_descriptions` (
`set_id` int(11) unsigned NOT NULL,
`set` varchar(255) NOT NULL default '',
`lang_code` char(2) NOT NULL default '',
PRIMARY KEY (`set_id`,`lang_code`)
) DEFAULT CHARSET UTF8;

CREATE TABLE IF NOT EXISTS `?:ab__product_sets_products` (
`set_id` int(11) unsigned NOT NULL,
`product_id` mediumint(8) NOT NULL,
PRIMARY KEY (`set_id`,`product_id`)
) DEFAULT CHARSET UTF8;
